#!/usr/bin/env bash
# Self-contained Linux installer and launcher for Mobile Terminal + tmux Manager.
set -Eeuo pipefail
umask 077

if [[ -z "${HOME:-}" ]]; then
  echo "ERROR: HOME is not set; run this script as a regular Linux user." >&2
  exit 1
fi
if (( EUID == 0 )); then
  echo "ERROR: Refusing to run the terminal manager as root. Run this launcher as a regular, least-privileged Linux user." >&2
  exit 1
fi

DATA_HOME="${XDG_DATA_HOME:-$HOME/.local/share}"
APP_ROOT="${TERMINAL_MANAGER_HOME:-$DATA_HOME/terminal-tmux-manager}"
mkdir -p "$APP_ROOT" "$APP_ROOT/bin" "$APP_ROOT/runtime" "$APP_ROOT/state"
APP_ROOT="$(cd "$APP_ROOT" && pwd -P)"
chmod 700 "$APP_ROOT" "$APP_ROOT/bin" "$APP_ROOT/runtime" "$APP_ROOT/state"

fail() { echo "ERROR: $*" >&2; exit 1; }
command_exists() { command -v "$1" >/dev/null 2>&1; }
SUDO=()
if (( EUID != 0 )) && command_exists sudo; then SUDO=(sudo); fi
run_as_root() {
  if (( EUID != 0 )) && ((${#SUDO[@]} == 0)); then
    fail "Installing missing system packages requires root or sudo. Install Node.js 18+, Python 3, tmux, curl, and tar, then rerun."
  fi
  "${SUDO[@]}" "$@"
}

install_packages() {
  local manager="" need=0
  local -a packages=()
  command_exists node || need=1
  command_exists tmux || need=1
  command_exists python3 || need=1
  command_exists curl || need=1
  command_exists sha256sum || need=1
  command_exists tar || need=1
  [[ -r /etc/ssl/certs/ca-certificates.crt || -r /etc/ssl/certs/ca-bundle.crt || -r /etc/pki/tls/certs/ca-bundle.crt ]] || need=1
  (( need )) || return 0
  if command_exists apt-get; then manager=apt
  elif command_exists dnf; then manager=dnf
  elif command_exists yum; then manager=yum
  elif command_exists pacman; then manager=pacman
  elif command_exists apk; then manager=apk
  else fail "Unsupported Linux package manager. Install Node.js 18+, Python 3, tmux, curl, sha256sum and tar, then rerun."; fi

  case "$manager" in
    apt)
      command_exists node || packages+=(nodejs)
      command_exists tmux || packages+=(tmux)
      command_exists python3 || packages+=(python3)
      command_exists curl || packages+=(curl)
      command_exists sha256sum || packages+=(coreutils)
      command_exists tar || packages+=(tar)
      [[ -r /etc/ssl/certs/ca-certificates.crt ]] || packages+=(ca-certificates)
      if ((${#packages[@]})); then run_as_root apt-get update; run_as_root apt-get install -y "${packages[@]}"; fi
      ;;
    dnf|yum)
      command_exists node || packages+=(nodejs)
      command_exists tmux || packages+=(tmux)
      command_exists python3 || packages+=(python3)
      command_exists curl || packages+=(curl)
      command_exists sha256sum || packages+=(coreutils)
      command_exists tar || packages+=(tar)
      [[ -r /etc/ssl/certs/ca-bundle.crt || -r /etc/pki/tls/certs/ca-bundle.crt ]] || packages+=(ca-certificates)
      if ((${#packages[@]})); then
        if [[ "$manager" == dnf ]]; then run_as_root dnf install -y "${packages[@]}"; else run_as_root yum install -y "${packages[@]}"; fi
      fi
      ;;
    pacman)
      command_exists node || packages+=(nodejs)
      command_exists tmux || packages+=(tmux)
      command_exists python3 || packages+=(python)
      command_exists curl || packages+=(curl)
      command_exists sha256sum || packages+=(coreutils)
      command_exists tar || packages+=(tar)
      [[ -d /etc/ssl/certs ]] || packages+=(ca-certificates)
      if ((${#packages[@]})); then run_as_root pacman -Sy --noconfirm --needed "${packages[@]}"; fi
      ;;
    apk)
      command_exists node || packages+=(nodejs)
      command_exists tmux || packages+=(tmux)
      command_exists python3 || packages+=(python3)
      command_exists curl || packages+=(curl)
      command_exists sha256sum || packages+=(coreutils)
      command_exists tar || packages+=(tar)
      [[ -d /etc/ssl/certs ]] || packages+=(ca-certificates)
      if ((${#packages[@]})); then run_as_root apk add --no-cache "${packages[@]}"; fi
      ;;
  esac
  command_exists node || fail "Node.js installation failed."
  command_exists tmux || fail "tmux installation failed."
  command_exists python3 || fail "Python 3 installation failed."
}

install_node22_if_needed() {
  local major arch file sums checksum base tmp
  major="$(node -p 'Number(process.versions.node.split(".")[0])' 2>/dev/null || echo 0)"
  if [[ "$major" =~ ^[0-9]+$ ]] && (( major >= 18 )); then return 0; fi
  echo "Node.js 18+ is required; installing a checksum-verified Node.js 22 runtime under $APP_ROOT/runtime."
  command_exists curl || fail "curl is required to install the compatible Node.js runtime."
  command_exists sha256sum || fail "sha256sum is required to verify the Node.js runtime."
  case "$(uname -m)" in
    x86_64|amd64) arch=x64 ;;
    aarch64|arm64) arch=arm64 ;;
    armv7l|armv7*) arch=armv7l ;;
    ppc64le) arch=ppc64le ;;
    s390x) arch=s390x ;;
    *) fail "No supported Node.js 22 runtime for architecture $(uname -m)." ;;
  esac
  base="https://nodejs.org/dist/latest-v22.x"
  sums="$(curl -fsSL "$base/SHASUMS256.txt")" || fail "Could not download the official Node.js checksums."
  file="$(printf '%s\n' "$sums" | awk -v a="$arch" '$2 ~ "^node-v[0-9]+\\.[0-9]+\\.[0-9]+-linux-" a "\\.tar\\.gz$" {print $2; exit}')"
  [[ -n "$file" ]] || fail "Could not find an official Node.js archive for $arch."
  checksum="$(printf '%s\n' "$sums" | awk -v f="$file" '$2 == f {print $1; exit}')"
  [[ "$checksum" =~ ^[[:xdigit:]]{64}$ ]] || fail "Could not read the official Node.js archive checksum."
  mkdir -p "$APP_ROOT/runtime/node22"
  tmp="$APP_ROOT/runtime/$file"
  curl -fL --retry 3 "$base/$file" -o "$tmp" || fail "Could not download Node.js."
  printf '%s  %s\n' "$checksum" "$tmp" | sha256sum -c - >/dev/null || fail "Node.js checksum verification failed."
  tar -xzf "$tmp" --strip-components=1 -C "$APP_ROOT/runtime/node22"
  rm -f "$tmp"
  PATH="$APP_ROOT/runtime/node22/bin:$PATH"
  export PATH
  node -e 'if (Number(process.versions.node.split(".")[0]) < 18) process.exit(1)' || fail "The installed Node.js runtime is too old."
}

install_packages
install_node22_if_needed

